"""Decision-oriented report, linked to the independently verified workbook snapshot."""
import json
from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parent;QA=ROOT/'qa'
OUT=ROOT.parent.parent/'outputs/flicker_teo_final/output';OUT.mkdir(parents=True,exist_ok=True)
d=json.loads((QA/'verified_results.json').read_text(encoding='utf-8'))
assert d['failed']==0, 'Do not author final narrative from an unverified numeric snapshot'
b=d['base'];sc=d['scenarios'][1];mc=d['mc']
def num(x,n=2):return f'{x:,.{n}f}'.replace(',',' ').replace('.',',').replace('-', '−')
def mln(x):return num(x/1e6)
def percent(x):return num(100*x)+'%'

doc=Document();sec=doc.sections[0]
sec.page_width=Inches(8.5);sec.page_height=Inches(11)
sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.75)
sec.header_distance=sec.footer_distance=Inches(.3)
normal=doc.styles['Normal'];normal.font.name='Arial';normal.font.size=Pt(10.5)
normal.paragraph_format.space_after=Pt(7);normal.paragraph_format.line_spacing=1.1
for name,size in [('Title',30),('Subtitle',16),('Heading 1',18),('Heading 2',12)]:
    s=doc.styles[name];s.font.name='Arial';s.font.size=Pt(size);s.font.color.rgb=RGBColor(0,0,0)
    s.paragraph_format.space_before=Pt(12);s.paragraph_format.space_after=Pt(8)
    s.paragraph_format.keep_with_next=True
    if name=='Title':
        s.font.underline=False
        for border in s.element.xpath('./w:pPr/w:pBdr'):border.getparent().remove(border)
header=sec.header.paragraphs[0];header.text='FLICKER  /  ТЕХНИКО ЭКОНОМИЧЕСКОЕ ОБОСНОВАНИЕ';header.style='Caption'
for r in header.runs:r.font.size=Pt(8);r.font.color.rgb=RGBColor.from_string('526174')
footer=sec.footer.paragraphs[0];footer.text='Версия 1.0 • 08 сентября 2026  |  '
fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
for r in footer.runs:r.font.size=Pt(8)
def p(t,style=None):return doc.add_paragraph(t,style)
def h(t):doc.add_heading(t,2)
def page(t):doc.add_page_break();doc.add_heading(t,1)
def table(head,rows,widths=None):
    t=doc.add_table(rows=1,cols=len(head));t.autofit=False
    if widths:
        for c,w in zip(t.columns,widths):c.width=Inches(w)
    for c,v in zip(t.rows[0].cells,head):c.text=str(v)
    for vals in rows:
        for c,v in zip(t.add_row().cells,vals):c.text=str(v)
    for i,row in enumerate(t.rows):
        trPr=row._tr.get_or_add_trPr();cant=OxmlElement('w:cantSplit');trPr.append(cant)
        if i==0:
            repeat=OxmlElement('w:tblHeader');trPr.append(repeat)
        for j,c in enumerate(row.cells):
            if widths:c.width=Inches(widths[j])
            pr=c._tc.get_or_add_tcPr();margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                el=OxmlElement('w:'+side);el.set(qn('w:w'),'85');el.set(qn('w:type'),'dxa');margins.append(el)
            pr.append(margins)
            border=OxmlElement('w:tcBorders')
            for side in ['top','left','bottom','right']:
                el=OxmlElement('w:'+side);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D8DEE7');border.append(el)
            pr.append(border)
            if i==0:
                sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'EDF0F4');pr.append(sh)
            for para in c.paragraphs:
                para.paragraph_format.space_after=Pt(3);para.paragraph_format.line_spacing=1.02
                for run in para.runs:run.font.size=Pt(9);run.bold=(i==0)
    p('');return t
def fig(name,caption,interpretation):
    doc.add_picture(str(QA/'figures'/f'{name}.png'),width=Inches(6.9))
    p(caption,'Caption');p(interpretation)

p('Flicker', 'Title')
p('Технико экономическое обоснование', 'Subtitle')
p('Для руководства и инвестиционного комитета Avito')
p('Версия 1.0\nДата анализа 08 сентября 2026 года\nГоризонт модели 60 месяцев от условного старта 01 октября 2026 года')
h('Предмет решения')
p('Flicker рассматривается как внутренний продукт раннего выявления ухудшения рабочего благополучия с последующими действиями HR. Обоснование оценивает расходы и возможный эффект удержания сотрудников. Доходы от продажи внешним клиентам в расчёт не включены.')
h('Основной вывод')
p(f'Масштабирование по текущим допущениям экономически не обосновано. Базовый экономический NPV составляет {mln(sc["npv"])} млн ₽, а годовой чистый эффект — {mln(sc["annualbenefit"]-sc["annualcost"])} млн ₽. Эти числа описывают условную модель, а не результаты Avito.')
p('Предлагается рассмотреть только двухмесячную подготовку инвестиционного решения с лимитом совокупного ресурса 1,80 млн ₽. Запуск пилота требует предварительного подтверждения допустимости данных, научного протокола, мощности и способности HR выполнять действия.')
h('Статус и авторство')
p('Аналитический проект документа подготовлен по двум предоставленным материалам Flicker и открытым первичным источникам. Внутреннее согласование Avito, результаты эксперимента и утверждённый бюджет отсутствуют. Версия FINAL означает завершённость подготовки и проверки документа, но не подтверждение эффективности продукта.')

page('Резюме для руководства')
p('Исходная книга уже показывала отрицательную экономику эксплуатации. Независимый пересчёт воспроизвёл восемь контрольных показателей. Исправление не направлено на получение положительного ROI: оно делает стоимость и причинную гипотезу проверяемыми.')
table(['Показатель базового сценария','Результат'],[
 ['Модельные предотвращённые уходы в год',num(b['count'])],['Экономическая стоимость одного ухода',num(b['exitcost'])+' ₽'],['Годовой экономический эффект',mln(sc['annualbenefit'])+' млн ₽'],['Годовая полная эксплуатация',mln(sc['annualcost'])+' млн ₽'],['Годовой чистый эффект',mln(sc['annualbenefit']-sc['annualcost'])+' млн ₽'],['Экономический NPV за 60 месяцев',mln(sc['npv'])+' млн ₽'],['Денежный NPV за 60 месяцев',mln(sc['cashnpv'])+' млн ₽'],['Окупаемость от начала проекта','Не окупается в пределах 60 месяцев']], [4.7,2.2])
p('Источник всех чисел таблицы — листы «Сценарии», «Удержание» и независимый помесячный пересчёт. Значения в ценах месяца 0 относятся к стабильному году эксплуатации; NPV включает индексацию и дисконтирование каждого месяца.')
h('Предлагаемое решение')
p(f'Одобрить рассмотрение S0 на два месяца, а не весь проект. Плановая оценка ресурса S0 равна {mln(b["phasecost"][0])} млн ₽ в ценах месяца 0 и {mln(b["stage0nominal"])} млн ₽ с помесячной индексацией. Лимит 1,80 млн ₽ — предлагаемое ограничение; при превышении сметы требуется повторное решение.')
p(f'При условной доле новых денежных затрат команды 50% расчёт cash для S0 составляет {mln(b["stage0cash"])} млн ₽ в ценах месяца 0. Это не заявка на подтверждённый бюджет: Finance должен отделить новый найм, уже оплачиваемый ресурс и внешние счета. Разница между cash и ресурсом не является бесплатной работой.')
p('Готовность к пилоту — не подтверждена. Готовность к масштабированию — отсутствует. Базовый сценарий экономически не оправдан. Изменить вывод могут проверенная стоимость ухода и реализуемость экономии, существенно более дешёвый способ действий, меньшая нагрузка опросов либо достаточный причинный эффект при подтверждённой мощности.')

page('Продукт и границы допустимых утверждений')
p('Бизнес-проблема формулируется как задержка между ухудшением условий работы, распознаванием проблемы и действием, которое работодатель способен выполнить. Общая распространённость выгорания сама по себе не определяет размер адресуемых потерь Avito. Размер проблемы должен быть рассчитан по внутренним уходам, их причинам, ролям и контрфактическим затратам.')
p('Предлагаемый механизм Flicker включает короткие повторные check-in, агрегированную обратную связь и организационные действия с владельцем и сроком. В контексте перечислены восемь факторов: ясность, смысл, признание, контроль, сплочённость, баланс жизни и работы, психологическая безопасность и энергия. Проверяемость этих факторов не равна способности предотвратить увольнение.')
h('Что известно о текущем продукте')
p('Предоставленный Master Context описывает MVP, а не независимо проверенный production-релиз. Есть несогласованность пяти факторов сотрудника и восьми факторов HR. В текущем эвристическом FBI большее значение означает худшее состояние; в целевой шкале здоровья предполагается обратное направление. Перед исследованием необходимо заморозить инструмент, направление шкалы и алгоритм. Изменение шкалы внутри эксперимента нарушит сопоставимость.')
p('Заявление об анонимности относится к видимости данных работодателем, но система хранит идентификаторы и индивидуальные записи. Порог не менее пяти различных респондентов должен применяться к каждой комбинации периода и фильтров; он не устраняет риск восстановления личности по пересечениям и повторным запросам. Текущая реализация этого контроля не подтверждена аудитом кода.')
h('Финансируемый периметр')
p('Оценка включает экспертно подготовленные рекомендации и организационные действия. Генеративный AI не требуется и не включён в финансируемый объём. Индивидуальная просьба о помощи должна быть отдельным добровольным потоком с явно указанным получателем; личные графики не должны автоматически передаваться HR. Интеграции, права, периодические окна и реальные тренды требуют отдельной корпоративной приёмки.')
p('Flicker нельзя представлять как медицинскую диагностику, инструмент индивидуального кадрового санкционирования или доказанную программу удержания. WHO рассматривает выгорание как профессиональный феномен, а рекомендации по психическому здоровью на работе поддерживают организационные меры, но не доказывают эффект данного продукта [S05–S06].')

