table(['Этап','FTE','Срок мес','Полный ресурс млн ₽'],[[name,num(b['fte'][i]),str([2,3,4,12,2,37][i]),mln(b['phasecost'][i])] for i,name in enumerate(['S0 Подготовка','S1 Разработка','S2 Пилот','S3 Валидация','S4 Масштабирование','S5 Эксплуатация'])],[2.8,1,1,2.1])
p('13 ролевых строк включают Product Lead, инженеров, аналитика, HR-эксперта, дизайн, QA, платформу, интеграции, HRBP, безопасность и юриста. Нулевая загрузка дополнительного инженера означает осознанное исключение роли из выбранного объёма. FTE — доля рабочего времени, а не автоматически новый штат. Методология, коммуникации, закупки, HR сопровождение и поддержка закреплены за этими ролями и не добавляются второй строкой.')
p('Новые денежные расходы команды отделены от перераспределяемого ресурса существующего бюджета. Внешняя корзина включает вычисления, мониторинг, резервирование, пентест и независимую экспертизу. Разовые счета распределены внутри соответствующего этапа; это допущение о сроках оплаты. Лицензии и внешние юридические счета пока неизвестны. Предположение об использовании доступных корпоративных инструментов должно быть проверено закупками.')
p(f'Плановый ресурс до решения о масштабировании составляет {mln(b["pre_scale"])} млн ₽ в ценах месяца 0. Это сумма последовательных этапов, а не текущий денежный запрос. Налоговый щит исключён: расчёт до налога. Для прямой корзины принят НДС 22% и полный вычет без временного лага. Фактическую возмещаемость, оборотный лаг и применимость тарифа проверяет Tax/Finance.')

page('Время сотрудников и распределение затрат')
fig('02_stages','Рисунок 2. Источник — «Стоимость Flicker», базовый сценарий. Единица — млн ₽ в ценах месяца 0.', 'Валидация и эксплуатация требуют существенного ресурса. Этап эксплуатации на графике длится 37 месяцев и поэтому не сопоставим с короткими этапами как месячный run-rate.')
p('Стоимость опросов рассчитывается открыто: численность × участие × частота × длительность / 60 × стоимость часа. Для 10 000 сотрудников, 70% участия, 52 check-in в год и трёх минут на один опрос получается 18 200 часов ежегодно. Используется средневзвешенная полная цена часа по ролям. Время руководителей учитывает все сигналы, включая ложные; обучение включено отдельно в пилот и масштабирование.')
p(f'Годовая альтернативная стоимость опросов в базе равна {mln(b["annual_survey"])} млн ₽; обработка сигналов руководителями — {mln(b["annual_manager"])} млн ₽. Это не обязательные денежные платежи. Переключатель «Учитывать время участников» позволяет показать результат без этой статьи, но не скрывает её из модели и не делает ресурс бесплатным.')
p('Резерв применяется один раз к команде и прямой корзине, отдельно распределяется на cash и ресурс. Он не является оценкой ожидаемого репутационного или юридического ущерба. Капитализация не меняет pre-tax cash flow; бухгалтерская классификация разработки должна быть согласована отдельно. Совокупная стоимость проекта включает также ресурс существующего бюджета, потому что его использование исключает альтернативные задачи.')
p('Для исключения пересечения затрат целевая численность опросов трактуется как аудитория вне команды поставки Flicker. Опрос, обработка сигнала руководителем и работа HRBP — разные действия; в бюджетировании их часы необходимо сверить с фактическими табелями, не добавляя повторно уже включённую загрузку.')

page('Сценарии и инвестиционные показатели')
fig('03_effect','Рисунок 3. Источник — «Сценарии», базовый стабильный год. Единица — млн ₽ в год в ценах месяца 0.',f'При эффекте {mln(sc["annualbenefit"])} млн ₽ и затратах {mln(sc["annualcost"])} млн ₽ эксплуатационный ROI составляет {percent((sc["annualbenefit"]-sc["annualcost"])/sc["annualcost"])}.')
table(['Сценарий','Эффект в год','Затраты в год','NPV 60 мес'],[[n,mln(x['annualbenefit']),mln(x['annualcost']),mln(x['npv'])] for n,x in zip(d['scenario_names'],d['scenarios'])],[2.3,1.5,1.5,1.6])
p('Все суммы таблицы — млн ₽; годовые показатели в ценах месяца 0, NPV номинальный. Оптимистичный сценарий означает более успешную программу, а не подбор всех минимальных расходов: повышение участия и качества действий связано с более дорогим сопровождением и дополнительной нагрузкой времени. Поэтому его NPV не обязан быть лучшим. Стресс включает задержку, рост стоимости и отрицательный причинный эффект.')
p('Вероятности четырёх сценариев неизвестны. Вероятностно-взвешенный NPV выводится как «не рассчитано». Ни базовый сценарий с вероятностью 100%, ни равные веса не навязываются. Иллюстративный Monte Carlo — отдельное распределение непрерывных драйверов; он не превращает эти сценарии в подтверждённый прогноз.')

page('Денежный поток и окупаемость')
fig('04_cashflow','Рисунок 4. Источник — «Денежный поток», базовый сценарий. Единица — млн ₽ накопленно от старта.', 'Экономический и денежный потоки не смешаны. Разрыв между ними отражает существующий ресурс команды, время участников и неденежную мощность удержанных сотрудников.')
p('В книге показаны месяц 0 и месяцы 1–60 для каждого сценария. Старт 01.10.2026 условный. Месяц 0 не содержит затрат; первый платёж приходится на месяц 1. Подготовка занимает два месяца, разработка три, пилот четыре, причинная валидация двенадцать, масштабирование два. Эффект признаётся только с месяца 24, после завершения масштабирования. Возможные ранние выгоды не включены.')
p('В базе годовой дисконт 20%, индексация труда 5%, прямой корзины 4%, стоимости ухода 5%. Все темпы являются допущениями, а не WACC Avito или макропрогнозом. Месячный дисконт равен (1 + годовая ставка)^(1/12) − 1. Остаточная стоимость по умолчанию равна нулю как явно исключённая выгода невалидированного IP.')
p('NPV — сумма дисконтированных экономических или денежных потоков. IRR определяется только при смене знака; в текущих сценариях её нет, поэтому выводится «не определена». Обычная и дисконтированная окупаемость отсчитываются от старта и в пределах горизонта не достигаются. Нулевой месяц не засчитывается как окупаемость.')
p('ROI эксплуатации относится к стабильному году; ROI проекта — к недисконтированным суммарным эффектам и затратам за весь горизонт. Benefit-cost ratio использует приведённые выгоды и затраты. Ограничение версии: основной горизонт фиксирован на 60 месяцах, налоговый эффект — на нуле; иной горизонт или post-tax постановка требует расширения модели и нового QA.')

page('Сравнение сценариев и чувствительность')
fig('05_scenarios','Рисунок 5. Источник — «Сценарии». Единица — экономический NPV за 60 месяцев, млн ₽.', 'Отрицательный результат устойчив к четырём выбранным сочетаниям. Это проверка этих сочетаний, а не доказательство отрицательного результата при любых возможных условиях.')
fig('06_tornado','Рисунок 6. Источник — «Чувствительность». Единица — экономический NPV, млн ₽. Диапазоны заданы как допущения.', 'Порядок отражает ширину выбранных диапазонов. Он не означает независимый причинный вклад параметров.')
p('Наибольший размах NPV в выполненном one-way анализе дают: '+', '.join(s['name'].lower() for s in sorted(d['sensitivity'],key=lambda x:-x['swing'])[:4])+'. Эти вводы следует проверять приоритетно. Изменение участия одновременно меняет эффект и стоимость времени; задержка продлевает валидацию и сдвигает начало эффекта. Сценарные зависимости не игнорируются в причинной интерпретации.')
p('Более высокий дисконт уменьшает приведённый убыток, а задержка в этой модели отодвигает дорогостоящую эксплуатацию. Такое улучшение отрицательного NPV не означает создания ценности или аргумента в пользу затягивания проекта.')

page('Пороги изменения решения')
fig('07_breakeven','Рисунок 7. Источник — «Пороги», «Удержание» и «Сценарии». Единицы — уходы в год и млн ₽ в год.',f'Для покрытия эксплуатации требуется {num(b["breakeven"])} предотвращённого ухода в год при доступном управляемом пуле 112. При текущей воронке требуемый причинный RRR равен {percent(b["rrrbreak"])} и физически недостижим.')
p('Операционная безубыточность не заменяет положительный NPV: необходимо также вернуть подготовку, разработку и валидацию с учётом времени. Двухфакторная таблица книги изменяет стоимость ухода и причинный RRR. Она показывает область изменения решения, не подбирая значение неизвестного параметра под желаемый результат.')
p('Порог стоимости одного ухода для окупаемости эксплуатации равен годовым затратам, делённым на ожидаемое число предотвращённых уходов. Порог для положительного NPV рассчитывается отдельно через приведённое число уходов за горизонт. Если экономика становится положительной только при неподтверждённом множителе ценности труда, масштабирование не обосновано до независимого подтверждения монетизации.')
p('Экономически важная альтернатива — снизить стоимость сбора данных и действий. Более редкие или короткие check-in, существующая инфраструктура и ограниченный ручной процесс могут изменить затраты, но также повлиять на выявляемость, доверие и эффект. Их нельзя считать бесплатными улучшениями без проверки совместного изменения этих параметров.')

page('Иллюстративный вероятностный анализ')
fig('10_montecarlo','Рисунок 8. Источник — «Вероятностный анализ» и независимая симуляция. Seed 20260908; 10 000 итераций; единица — млн ₽ NPV.', 'Распределение отражает выбранные допущения низкой уверенности. Оно не является оценённой вероятностью успеха Avito и не включает неизвестные юридические хвосты.')
table(['Метрика','Результат'],[['P10 / P50 / P90 NPV',f'{mln(mc["p10"])} / {mln(mc["p50"])} / {mln(mc["p90"])} млн ₽'],['P NPV больше нуля',percent(mc['positive'])],['Окупаемость за 3 / 5 лет',percent(mc['pay3'])+' / '+percent(mc['pay5'])],['Expected loss',mln(mc['expected_loss'])+' млн ₽'],['Downside at risk',mln(mc['downside_at_risk'])+' млн ₽']], [3.2,3.7])
p('Expected loss определён как E[max(−NPV, 0)] для всей выборки, а не средний убыток только среди неудач. Downside-at-risk определён как −P10(NPV), не как условный tail loss. Вероятности окупаемости рассчитаны по неотрицательному накопленному экономическому потоку на месяцах 36 и 60; для выбранных стационарных после запуска потоков это соответствует возврату вложений к указанным датам.')
p('Команда, стоимость ухода, текучесть, участие, причинный RRR и дисконт имеют редактируемые треугольные распределения; задержка равномерна на целых месяцах 0–6. Общий базовый uniform связывает стоимость команды с задержкой, другой — участие с RRR. Это условная сонаправленная зависимость, не эмпирическая корреляция. Остальные пары независимы по допущению. Нулевая частота успехов в 10 000 испытаний не доказывает невозможность успеха.')
p('Наиболее сильные ранговые связи NPV в этой выборке: '+', '.join(x['name'].lower()+' '+num(x['spearman']) for x in sorted(mc['drivers'],key=lambda x:-abs(x['spearman']))[:3])+'. Это коэффициенты Спирмена, а не независимые доли объяснённого эффекта. Отрицательная связь RRR с NPV в совместной выборке обусловлена его заданной зависимостью с участием и затратами времени; one-way причинное повышение RRR улучшает эффект.')

page('Риски и управление отрицательным результатом')
fig('08_risks','Рисунок 9. Источник — «Риски», аналитическая классификация A01. Числовая вероятность и тяжесть неизвестны.', 'На карте показана потребность контроля по этапам. Она намеренно не изображает неизвестные вероятности и ущерб как измеренные значения.')
p('Главные механизмы отрицательного результата — невалидный сигнал, недостаточная мощность, отсутствие причинного эффекта, низкое участие, response bias и невозможность полезных действий HR. Отдельно выделены вредные интервенции, приватность и восстановление личности, задержки интеграций, увеличение объёма и перегрузка команды. Сопротивление сотрудников и руководителей способно ухудшить одновременно участие, доверие и качество действий.')
p('Реестр включает этап, финансовый механизм, владельца функции, меру снижения, конкретную ячейку, способ учёта, вероятность, изменения сроков и эффектов, валовое и остаточное влияние и ожидаемую стоимость. Вероятности и денежный ущерб оставлены неизвестными. Функции владельцев указаны как требуемые, а не как уже полученное согласование Avito.')
p('Сценарий и резерв не должны повторно включать один и тот же риск. Если денежный ущерб уже выражен задержкой или снижением RRR, нельзя прибавлять ещё один ожидаемый ущерб за тот же механизм. Репутационные, юридические и регуляторные хвосты пока вне количественной оценки; это открытый периметр риска, а не нулевая ответственность.')

page('Альтернативы реализации')
p('Выбор должен сравнивать разные способы получить допустимые данные и выполнить полезное действие, а не только разные версии полного продукта. У альтернатив нет подтверждённых коммерческих предложений или внутренних смет; их цены и NPV не подставлены нулями. В книге есть структура запроса и пороги допустимой стоимости.')
table(['Вариант','Экономика и критерий выбора'],[
 ['Ничего не менять','Инкрементальные затраты и эффект программы равны нулю по определению базы сравнения; NPV 0. Существующие проблемы и текущие расходы сохраняются.'],
 ['Улучшить существующие опросы','Цена запуска, ежегодная нагрузка и эффект неизвестны. Предпочтителен, если доступны данные и владельцы действий при меньшей полной стоимости.'],
 ['Облегчённый Flicker','Ручная экспертная обработка и минимум интеграций. Проверить capacity HR, стоимость сигнала и устойчивость приватности; автоматический масштаб не обещается.'],
 ['Купить или адаптировать HRTech','Запросить цену на сотрудника, внедрение, интеграции, хранение, выход и перенос данных. Vendor claims не заменяют причинный outcome.'],
 ['Полный Flicker','Расчёт представлен в этой модели. Даёт больший контроль реализации, но требует корпоративной разработки и валидации; текущий NPV отрицателен.']], [2,4.9])
p('Для каждого варианта нужны запуск, ежегодная стоимость, сроки до эффекта, ожидаемое удержание и его интервал, время сотрудников, privacy архитектура, права и управляемость, зависимость от поставщика, интеграции и риск остановки. Для закупки особенно важны договорные границы доступа к персональным данным и стоимость выхода. Сроки должны включать исследование, а не только техническое внедрение.')
p('При одинаковом эффекте сравнивать приведённую полную стоимость и денежный лимит. При различном эффекте сравнивать разницу NPV относительно текущей практики. Порог годовых расходов равен проверенному годовому эффекту лишь при нулевых инвестициях и без дисконтирования; это предварительный экран, не инвестиционный критерий. Положительный NPV требует отдельного помесячного расчёта цены запуска и задержки эффекта.')
p('На S0 целесообразно получить сопоставимые предложения по улучшению текущих опросов, облегчённому процессу и внешнему решению. Пока нет оснований считать полный Flicker дешевле или эффективнее этих вариантов. Отказ от полного масштаба может быть рациональным итогом подготовки.')

page('Пилот и программа научной валидации')
p('Предпочтителен кластерный рандомизированный эксперимент с командой как единицей назначения. Стратификация по подразделению, размеру и исходной текучести уменьшает дисбаланс. Контроль продолжает обычную практику; интервенция получает программу Flicker вместе с заранее определённым набором действий HR. Анализ проводится по исходному назначению всех включённых сотрудников — intention to treat, независимо от ответов на опросы.')
h('Outcome и горизонт')
p('Первичный outcome — 12-месячный кумулятивный риск добровольного нежелательного ухода. Правила нежелательности фиксируются до раскрытия назначения, по возможности оцениваются независимым экспертом. Вторичные outcomes: участие, доверие, жалобы, выполнение действий, психометрические свойства и вневыборочные recall/precision. Психометрическая валидность, прогноз риска и причинная эффективность — три отдельные задачи.')
h('Мощность и минимальный эффект')
p(f'Иллюстративный план 5 000 сотрудников, средняя команда 50, ICC 0,02 и потеря outcome 10% даёт design effect 1,98. При baseline 3,2%, двусторонней α = 5% и мощности 80% приблизительный MDE равен {num(b["mde"]*100)} процентного пункта. Плановая мощность на эффект, соответствующий текущей воронке, составляет {percent(b["power"])}. Приближённая требуемая общая выборка — {num(b["required_n"],0)} сотрудников.')
p('Эти расчёты не одобряют эксперимент. Использована нормальная аппроксимация с равными кластерами и дисперсией под нулевой гипотезой [S07]. Реальные размеры команд, ICC, редкие события, неодинаковый набор, кластерные степени свободы и миграции требуют симуляционного расчёта статистиком. Если эффект нельзя обнаружить доступной выборкой и приемлемым сроком, исследование удержания следует переработать или не запускать.')
h('Пропуски и правила анализа')
p('До рандомизации исключаются команды без допустимого HRIS outcome, с неизбежной реорганизацией или без владельца действий. После назначения неответившие не исключаются; миграции фиксируются. Неответ на check-in не означает благополучие. Отчёт содержит потерю наблюдения по группам, причины и анализ крайних границ; множественная импутация допустима при обосновании MAR, с чувствительностью к MNAR. План анализа, primary outcome и множественные сравнения регистрируются до получения результатов.')

page('Решения по результатам исследования')
p('Если одновременная рандомизация невозможна, рассматривается случайный порядок внедрения stepped-wedge с поправкой на календарное время и внутрикомандные корреляции [S08]. Difference-in-differences — более слабая альтернатива: нужны сопоставимые группы, отсутствие предвосхищения, проверка предтрендов и чувствительность к отклонениям от параллельных трендов [S09]. Исторический backtest проверяет выявляемость, но не предотвращение увольнений.')
h('Критерии успеха и досрочной остановки')
p('До запуска согласовать минимально полезный эффект и финансовый порог. Масштабирование требует, чтобы нижняя доверительная граница эффекта при проверенной монетизации покрывала полную стоимость, а NPV был положительным. Доверительный интервал, включающий экономически важный вред, не позволяет утверждать отсутствие вреда. Статистическая значимость без полезной величины эффекта недостаточна.')
p('Предлагаемые пилотные operational gates: регулярное участие не ниже 70%, допустимость агрегатов не ниже 90%, выполненные действия в SLA не ниже 80%. Это проектные пороги, а не факты или научные универсалии. Recall и precision должны иметь заранее согласованные минимумы и доверительные интервалы на отдельной выборке; пороги пока неизвестны и требуют решения на S0.')
p('Немедленная приостановка требуется при утечке, восстановлении личности, принуждении, вредных интервенциях или использовании данных для санкций вне согласованного назначения. Досрочный анализ эффективности допустим только по заранее заданному последовательному плану; регулярное просматривание p-value без поправки не допускается. Решение об остановке принимает независимый владелец безопасности и исследования, а не только продуктовая команда.')
h('Монетизация наблюдаемого результата')
p('Умножить ITT абсолютную разницу риска на согласованную целевую численность, затем на роль-специфическую разницу затрат между удержанием и уходом. Отдельно показать денежную часть, время и мощность, интервалы эффекта и чувствительность монетизации. Перенос на другие роли и масштабы — новая гипотеза; обнаружение сигнала само по себе не разрешает признавать экономическую выгоду.')
p('Четырёхмесячный ранний пилот проверяет реализуемость, доверие и процесс. Он не может быть назван завершённой проверкой 12-месячного удержания. Расширенная валидация планируется отдельно, а её бюджет зависит от реального power gate.')

page('Этапы и ограничение суммы под риском')
fig('09_timeline','Рисунок 10. Источник — «Этапы» и «Стоимость Flicker», базовый график. Единица — месяцы от старта.', 'Продолжение не автоматическое. Финансирование следующего этапа разрешается только после рассмотрения результатов предыдущего.')
table(['Gate','Результат и решение'],[
 ['S0 → S1','Согласовать данные, privacy архитектуру, владельцев действий, power plan, смету и сравнение альтернатив. STOP при недоступности данных или бессмысленном исследовании.'],
 ['S1 → S2','Корпоративная приёмка, безопасность, стабильный инструмент и зарегистрированный протокол. STOP при блокере; ITERATE при исправимых дефектах.'],
 ['S2 → S3','Проверить участие, допустимые агрегаты, действия, доверие и точность; подтвердить реализуемую мощность.'],
 ['S3 → S4','Положительная причинная и экономическая оценка с интервалами; утверждённая смета и отсутствие открытых критических инцидентов.'],
 ['S4 → S5','Приёмка интеграций, обучения, поддержки и переноса эффекта. Ежегодно перепроверять экономику и безопасность.']], [1.2,5.7])
p('Накопленная стоимость в книге — плановая экспозиция в ценах месяца 0, а не гарантированный максимум ущерба. Единственный предлагаемый жёсткий лимит сейчас — 1,80 млн ₽ ресурса S0. Лимиты следующих этапов должны устанавливаться перед их разрешением; пока они неизвестны. Без нового решения дополнительные обязательства принимать нельзя. Ни сумма всего горизонта, ни ресурс до масштаба не должны автоматически становиться текущим cash запросом.')

page('Стоимость неудачи и ценность информации')
p('Expected cost to failure рассчитывается как сумма произведений вероятности дойти до этапа, условной вероятности провала на нём и накопленных затрат к этому решению. В книге есть редактируемые условные вероятности и формулы. Пока они неизвестны, результат «не рассчитано» корректнее произвольного числа. Это стоимость ветвей остановки, а не полный ожидаемый бюджет, который дополнительно включает ветвь успешного продолжения.')
p('Ценность исследования зависит от того, способно ли новое знание изменить выбор. Валовая EVSI равна E[max(0, E[NPV | данные])] − max(0, E[NPV]). Чистая ценность информации вычитает стоимость её получения. Без prior, модели возможных результатов и правил решения обе величины не оценены. Нельзя назвать всю потенциальную экономию предотвращённого ошибочного масштаба ценностью S0.')
table(['Этап','Информация для решения','Что пока неизвестно'],[
 ['S0','Доступ к данным, смета, альтернативы, реализуемость исследования','Вероятность, что сведения изменят выбор'],['S1','Валидность измерения, безопасность, техническая выполнимость','Вероятность успешной приёмки'],['S2','Участие, доверие, точность, способность действовать','Стабильность процесса и переносимость'],['S3','Причинный эффект и интервал, монетизация','Распределение итогов исследования'],['S4','Переносимость, интеграции и поддержка','Эффект и нагрузка на новом масштабе'],['S5','Устойчивость эффекта и расходов','Изменения условий и долгосрочный вред']], [0.7,3.6,2.6])
p('При настолько отрицательной базовой экономике дешёвая подготовка рациональна только если есть реалистичные пути изменить ключевые параметры или выбрать лучшую альтернативу. Рекомендация рассмотреть лимит 1,80 млн ₽ не является доказательством положительной EVSI. Комитет вправе отказать в S0, если нужные сведения можно получить меньшими ресурсами или уже известно, что доступный эффект не покроет даже облегчённое решение.')

page('Запрос внутренних данных и независимая рекомендация')
table(['Приоритет','Данные и назначение','Владелец функции'],[
 ['До S0 решения','Целевая популяция, текущие опросы, разрешённое назначение данных','HRD / People Analytics'],['До S1','Regrettable outcomes, причины, размеры команд, ICC и missingness','People Analytics / Research'],['До S1','Ролевые ставки, новый cash, существующие FTE, бонус и налоги','C&B / Finance / Tax'],['До S1','Найм, вакансии, экономия оплаты, замещение, ramp-up, ценность мощности','Talent Acquisition / Finance'],['До S1','Доступ, хранения и удаления, фильтры агрегатов, отдельный поток помощи','Privacy / InfoSec / Legal'],['До S1','Сопоставимые сметы пяти альтернатив, лицензии и договоры','Procurement / Product Lead'],['До S2','Владелец каждого действия, SLA, capacity и протокол вреда','HRBP / Руководители'],['До S4','ITT эффект и интервалы, фактические затраты, границы переноса','Research / Finance']], [1.1,4.2,1.6])
p('Все владельцы указаны как необходимые функции; конкретные назначения и сроки внутри Avito не подтверждены. Подробный исходный запрос сохранён и дополнен в книге. Недостающие внутренние показатели не заменены публичными бенчмарками или нулями.')
h('Независимая рекомендация')
p('Не запускать масштабирование и не утверждать полный бюджет по текущей модели. Не представлять 11,85 предотвращённых уходов как наблюдённый факт. Пилот может быть разрешён только после privacy и power gate, утверждения инструмента и выполнения действий. Предпочтительный следующий шаг — ограниченная подготовка решения и сравнение менее дорогих альтернатив.')
p('Числа способны существенно измениться после проверки вакансий и стоимости мощности, структуры расходов команды и времени check-in. Но до таких данных отрицательная экономика не должна маскироваться включением неподтверждённой производительности, выручки, сокращения больничных или повторным учётом потери знаний.')
h('Ограничения')
p('Это conditional pre-tax модель с неполными внутренними данными. Распределения и корреляции иллюстративны, научный инструмент не валидирован, коммерческие цены отсутствуют, правовые хвосты не оценены. Номинальный cash flow предполагает равномерную оплату внутри этапов и отсутствие лага НДС. Проверенный документ не заменяет финансовую, юридическую и научную приёмку Avito.')

page('Формулы и словарь показателей')
table(['Показатель','Определение'],[
 ['Нежелательный уход','Добровольный уход, отвечающий заранее зафиксированным regrettable критериям'],['Причинный RRR','1 − риск интервенции / риск корректного контроля в определённой популяции'],['ITT ARR','Риск контроля − риск интервенции среди всех назначенных сотрудников'],['Эффект удержания','Ожидаемое число предотвращённых уходов × проверенная стоимость ухода'],['NPV','Σ CF_m / (1 + r_год)^(m/12), m от 0 до 60'],['ROI эксплуатации','(Годовая выгода − годовые затраты) / годовые затраты'],['ROI проекта','(Сумма выгод − сумма затрат) / сумма затрат за весь горизонт'],['BCR','Приведённые выгоды / приведённые затраты'],['Break even уходов','Годовые затраты / экономическая стоимость одного ухода'],['Мощность','Вероятность отклонить H0 при заранее заданном истинном эффекте'],['MDE','Минимальная разница риска при заданных α, мощности и дизайне'],['FTE','Доля полной месячной загрузки, не обязательная новая штатная единица']], [2.1,4.8])
p('Cash показывает новые денежные расходы и реализуемые денежные выгоды; экономический поток дополнительно включает перераспределённый ресурс, альтернативную стоимость времени и условную стоимость мощности. Выручка в модели отсутствует. Упущенная зарплата, неденежный ресурс и платёж поставщику не должны называться одним видом экономии.')
p('Оригинал и исправленная версия сверяются в листе «Аудит». Финансовые формулы, сценарные вводы, регистр источников, автоматические и независимые проверки входят в сопровождающий XLSX. Отдельный аудит описывает воспроизводимость, неизменность источников, мост изменений, границы проверки и допустимые утверждения.')

